-- 1. Parent partitioned table
CREATE TABLE audit_logs (
    id UUID NOT NULL,
    action VARCHAR(50) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL
) PARTITION BY RANGE (created_at);

-- 2. Create partition for 2024
CREATE TABLE audit_logs_2024 PARTITION OF audit_logs
    FOR VALUES FROM ('2024-01-01 00:00:00Z') TO ('2025-01-01 00:00:00Z');

-- 3. Create partition for 2025
CREATE TABLE audit_logs_2025 PARTITION OF audit_logs
    FOR VALUES FROM ('2025-01-01 00:00:00Z') TO ('2026-01-01 00:00:00Z');

-- Create next month's partition before writes need it
CREATE TABLE orders_2024_07 PARTITION OF orders
FOR VALUES FROM ('2024-07-01') TO ('2024-08-01');

-- Confirm pruning: only the July partition is read
EXPLAIN (COSTS false)
SELECT count(*)
FROM orders
WHERE ordered_at >= DATE '2024-07-01'
  AND ordered_at <  DATE '2024-08-01';

-- Expire an old partition in O(1) instead of a huge DELETE
ALTER TABLE orders DETACH PARTITION orders_2023_01;
DROP TABLE orders_2023_01;
